/**
 * Emoji, offline (docs/design/captions-studio.md §11.3): suggestions from the words, the
 * sensitive-topic guard, and emoji keys. The keyword data comes from emojiData.ts (generated by
 * scripts/build-emoji-data.mjs); the emoji that can be drawn from emojiList.ts.
 *
 * CONTRACT (part P4): signatures are frozen; bodies are to be written.
 */
import type { EmojiGraphic, Project } from '../types'

/** The body of a frozen signature part P4 writes. */
function notImplemented(name: string, ...args: unknown[]): never {
  void args
  throw new Error(`${name}: not implemented (Captions Studio part P4)`)
}

/** Emoji anchored to their words, at most one per 8 s, with the guards of §11.3. */
export function suggestEmoji(project: Project): EmojiGraphic[] {
  return notImplemented('suggestEmoji', project)
}

/** Whether a caption is about a sensitive topic (no emoji or keyword pop-ups on it). */
export function isSensitive(text: string, language?: string): boolean {
  return notImplemented('isSensitive', text, language)
}

/** The key of an emoji as typed: code points in hex joined by '-', without FE0F. */
export function emojiKey(emoji: string): string {
  return notImplemented('emojiKey', emoji)
}
